input.script:
const cb = document.querySelector('input[type="checkbox"]');
if (cb) {
  cb.click();
  return 'clicked';
}
return 'not found';

const iframe = document.querySelector('iframe[src*="challenges.cloudflare"]');
if (iframe) {
  return iframe.src;
}
return 'no iframe found';

const cb = document.querySelector('input[type="checkbox"]');
if (cb) {
  const rect = cb.getBoundingClientRect();
  return {x: rect.x, y: rect.y, w: rect.width, h: rect.height, visible: rect.width > 0};
}
return 'not found';

const cb = document.querySelector('input[type="checkbox"]');
if (cb) {
  cb.focus();
  return {tagName: cb.tagName, type: cb.type, id: cb.id, name: cb.name};
}
return 'not found';

const cb = document.querySelector('input[type="checkbox"]');
if (cb) {
  cb.dispatchEvent(new MouseEvent('mousedown', {bubbles: true}));
  cb.dispatchEvent(new MouseEvent('mouseup', {bubbles: true}));
  cb.dispatchEvent(new MouseEvent('click', {bubbles: true}));
  return 'clicked';
}
return 'not found';

const iframe = document.querySelector('iframe');
if (iframe) {
  try {
    const doc = iframe.contentDocument;
    if (doc) {
      const cb = doc.querySelector('input[type="checkbox"]');
      if (cb) {
        cb.click();
        return 'iframe cb clicked';
      }
      return 'no cb in iframe';
    }
    return 'iframe cross-origin';
  } catch (e) {
    return 'error: ' + e.message;
  }
}
return 'no iframe';

const allInputs = document.querySelectorAll('input');
const allCheckboxes = document.querySelectorAll('[role=checkbox]');
const allButtons = document.querySelectorAll('button');
return {
  inputs: allInputs.length,
  checkboxes: allCheckboxes.length,
  buttons: allButtons.length,
  bodyHTML: document.body.outerHTML.substring(0, 2000)
};

const cb = document.querySelector('input[type="checkbox"]');
const widget = document.querySelector('[role=alert]');
return {
  hasCheckbox: !!cb,
  hasWidget: !!widget,
  cbInfo: cb ? {tag: cb.tagName, type: cb.type, offsetWidth: cb.offsetWidth, offsetHeight: cb.offsetHeight} : null,
  widgetInfo: widget ? {tag: widget.tagName, role: widget.getAttribute('role'), html: widget.outerHTML.substring(0, 500)} : null,
  // Find any element containing "verify" or "human" or "robot"
  texts: Array.from(document.querySelectorAll('*')).filter(el => el.textContent && (el.textContent.includes('验证') || el.textContent.includes('human'))).slice(0, 5).map(el => ({tag: el.tagName, text: el.textContent.substring(0, 100)}))
};
